using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
namespace RebirthEntityStudio {
 public static class RebirthNativeHairReferenceRender {
  const string Root="C:/Program Files (x86)/Steam/steamapps/common/7 Days To Die/Data/Addressables/Standalone";
  static readonly Dictionary<string,AssetBundle> loaded=new Dictionary<string,AssetBundle>();
  static AssetBundle Bundle(string relative){AssetBundle b;if(loaded.TryGetValue(relative,out b))return b;b=AssetBundle.LoadFromFile(Root+"/"+relative);if(b==null)throw new IOException("Cannot load native reference: "+relative);loaded[relative]=b;return b;}
  static GameObject Model(AssetBundle b,string wanted=null){return b.LoadAllAssets<GameObject>().First(p=>(wanted==null||p.name==wanted)&&p.GetComponentsInChildren<SkinnedMeshRenderer>(true).Any(r=>r.sharedMesh!=null));}
  static void Draw(PreviewRenderUtility preview,GameObject model){foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>(true)){var mesh=r.sharedMesh;if(mesh==null)continue;for(int sub=0;sub<Mathf.Min(mesh.subMeshCount,r.sharedMaterials.Length);sub++){var mat=r.sharedMaterials[sub];if(mat!=null)preview.DrawMesh(mesh,r.localToWorldMatrix,mat,sub);}}}
  [Serializable] public sealed class NativeMaterialReceipt {public string shader,swatch,colourSpace;public Color tint,cuticle,cortex;public float idVariation,rootDarkening;}
  [Serializable] public sealed class SurfaceRecord {public string name;public Vector3[] vertices;public int[] triangles;}
  [Serializable] public sealed class SurfaceSet {public SurfaceRecord[] surfaces;}
  public static void PrepareFit(){try{
   string output=Environment.GetEnvironmentVariable("REBIRTH_APPEARANCE_OUTPUT");string gender=Environment.GetEnvironmentVariable("REBIRTH_NATIVE_HEAD_GENDER")??"female";string label=gender=="male"?"Male":"Female";foreach(string p in Directory.GetFiles(Root,"*unitybuiltinshaders.bundle"))AssetBundle.LoadFromFile(p);Bundle("shaders_assets_all.bundle");Bundle("player_assets_entities/player/common.bundle");Bundle("player_assets_entities/player/"+gender+"/common.bundle");
   var model=Model(Bundle("player_assets_entities/player/"+gender+"/heads/white/01.bundle"));var records=new List<SurfaceRecord>();var rows=new List<string>();
   foreach(var renderer in model.GetComponentsInChildren<SkinnedMeshRenderer>(true)){var mesh=renderer.sharedMesh;rows.Add(renderer.name+" mesh="+mesh.name+" bounds="+mesh.bounds+" materials="+string.Join(",",renderer.sharedMaterials.Select(m=>m?m.name:"null")));using(var read=MeshUtility.AcquireReadOnlyMeshData(mesh)){var points=new Unity.Collections.NativeArray<Vector3>(mesh.vertexCount,Unity.Collections.Allocator.Temp);read[0].GetVertices(points);records.Add(new SurfaceRecord{name=renderer.name,vertices=points.Select(p=>renderer.localToWorldMatrix.MultiplyPoint3x4(p)).ToArray(),triangles=mesh.triangles});points.Dispose();}}
   File.WriteAllText(Path.Combine(output,"Native"+label+"HeadSurfaces.json"),JsonUtility.ToJson(new SurfaceSet{surfaces=records.ToArray()}));File.WriteAllLines(Path.Combine(output,"Native"+label+"HeadSurfaces.txt"),rows);
   var template=RebirthFaceGeneratorWindow.ReadTemplate();var recipe=JsonUtility.FromJson<FaceRecipe>(File.ReadAllText(Path.Combine(output,"FaceSettings.json")));recipe.Validate(template);var head=RebirthFaceGeneratorModel.Build(template,recipe);File.WriteAllText(Path.Combine(output,"GeneratedHeadSurface.json"),JsonUtility.ToJson(new SurfaceRecord{name="Generated skin",vertices=head.vertices,triangles=head.GetTriangles(0)}));UnityEngine.Object.DestroyImmediate(head);Debug.Log("REBIRTH_NATIVE_FIT_SURFACES_READY");EditorApplication.Exit(0);
  }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
  public static void FacialFittedReview(){try{
   string output=Environment.GetEnvironmentVariable("REBIRTH_APPEARANCE_OUTPUT"),data=Path.Combine(output,"NativeFacialHairFit/Smooth_2"),review=Path.Combine(data,"Review_2");Directory.CreateDirectory(review);foreach(string p in Directory.GetFiles(Root,"*unitybuiltinshaders.bundle"))AssetBundle.LoadFromFile(p);Bundle("shaders_assets_all.bundle");Bundle("player_assets_entities/player/common.bundle");Bundle("player_assets_entities/player/male/common.bundle");
   var template=RebirthFaceGeneratorWindow.ReadTemplate();var recipe=JsonUtility.FromJson<FaceRecipe>(File.ReadAllText(Path.Combine(output,"FaceSettings.json")));recipe.Validate(template);var head=RebirthFaceGeneratorModel.Build(template,recipe);var skin=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(recipe.generatedMaterialGuid));var eyes=RebirthFaceAppearance.EyeMaterial(recipe);var oral=RebirthFaceGeneratorWindow.CreateOralMaterials(recipe);var colours=JsonUtility.FromJson<NativeHairColourCatalog>(File.ReadAllText(Path.Combine(output,"NativeHairFit/Swatches.json")));var colour=colours.swatches.Single(s=>s.name=="06 Black");
   foreach(var style in new[]{new[]{"beard","hair_facial_beard3"},new[]{"mustache","hair_facial_mustache3"},new[]{"chops","hair_facial_sideburns3"}}){var source=Model(Bundle("player_assets_entities/player/male/facialhair/"+style[0]+".bundle"),style[1]).GetComponentsInChildren<SkinnedMeshRenderer>(true).First(r=>r.sharedMesh!=null);var fitted=JsonUtility.FromJson<NativeFittedVertices>(File.ReadAllText(Path.Combine(data,style[1]+".json")));var hair=RebirthNativeHairFit.BuildSurfaceFit(source.sharedMesh,fitted);var mat=RebirthNativeHairFit.Colour(source.sharedMaterial,colour);RebirthNativeHairFit.Finish(mat,.2f,.15f,.2f);var preview=new PreviewRenderUtility();try{foreach(int angle in new[]{0,30,90}){preview.BeginStaticPreview(new Rect(0,0,1536,1536));RebirthFaceGeneratorWindow.ConfigurePreview(preview,new Vector2(angle,0),.19f,false,null);preview.camera.renderingPath=UnityEngine.RenderingPath.DeferredShading;UnityEngine.Rendering.GraphicsSettings.lightsUseLinearIntensity=false;preview.DrawMesh(head,Matrix4x4.identity,skin,0);preview.DrawMesh(head,Matrix4x4.identity,eyes,1);RebirthFaceGeneratorWindow.DrawOral(preview,head,oral);preview.DrawMesh(hair,Matrix4x4.identity,mat,0);preview.Render();var image=preview.EndStaticPreview();File.WriteAllBytes(Path.Combine(review,"Fitted_"+style[0]+"_"+angle+".png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}}finally{preview.Cleanup();UnityEngine.Object.DestroyImmediate(hair);UnityEngine.Object.DestroyImmediate(mat);}}
   Debug.Log("REBIRTH_NATIVE_FACIAL_FITTED_READY");EditorApplication.Exit(0);
  }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
  public static void FittedReview(){try{
   string output=Environment.GetEnvironmentVariable("REBIRTH_APPEARANCE_OUTPUT"),data=Path.Combine(output,"NativeHairFit");foreach(string p in Directory.GetFiles(Root,"*unitybuiltinshaders.bundle"))AssetBundle.LoadFromFile(p);Bundle("shaders_assets_all.bundle");Bundle("player_assets_entities/player/common.bundle");Bundle("player_assets_entities/player/female/common.bundle");
   var template=RebirthFaceGeneratorWindow.ReadTemplate();var recipe=JsonUtility.FromJson<FaceRecipe>(File.ReadAllText(Path.Combine(output,"FaceSettings.json")));recipe.Validate(template);var head=RebirthFaceGeneratorModel.Build(template,recipe);var skin=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(recipe.generatedMaterialGuid));var eyes=RebirthFaceAppearance.EyeMaterial(recipe);var oral=RebirthFaceGeneratorWindow.CreateOralMaterials(recipe);var cage=JsonUtility.FromJson<NativeCrownCage>(File.ReadAllText(Path.Combine(data,"Cage.json")));var colours=JsonUtility.FromJson<NativeHairColourCatalog>(File.ReadAllText(Path.Combine(data,"Swatches.json")));var blond=colours.swatches.Single(s=>s.name=="01 Blond");string review=Path.Combine(data,"Review_DryNative");Directory.CreateDirectory(review);
   foreach(string style in new[]{"midpart_shoulder"}){string key="hair_"+style;var source=Model(Bundle("player_assets_entities/player/female/hair/"+style+".bundle"),key).GetComponentsInChildren<SkinnedMeshRenderer>(true).First(r=>r.sharedMesh!=null);var fitted=JsonUtility.FromJson<NativeFittedVertices>(File.ReadAllText(Path.Combine(data,key+".json")));var hair=RebirthNativeHairFit.Build(source.sharedMesh,fitted,cage);var mat=RebirthNativeHairFit.Colour(source.sharedMaterial,blond);RebirthNativeHairFit.Finish(mat,.2f,.15f,.2f);File.WriteAllText(Path.Combine(review,"MaterialReceipt.json"),JsonUtility.ToJson(new NativeMaterialReceipt{shader=mat.shader.name,swatch=blond.name,tint=mat.GetColor("_Tint1"),cuticle=mat.GetColor("_CuticleSpecularColor"),cortex=mat.GetColor("_CortexSpecularColor"),idVariation=mat.GetFloat("_IDMapStrength"),rootDarkening=mat.GetFloat("_RootDarkening"),colourSpace=QualitySettings.activeColorSpace.ToString()},true));var preview=new PreviewRenderUtility();try{foreach(int angle in new[]{0,30,90,180}){preview.BeginStaticPreview(new Rect(0,0,1536,1536));RebirthFaceGeneratorWindow.ConfigurePreview(preview,new Vector2(angle,0),.24f,false,null);preview.camera.renderingPath=UnityEngine.RenderingPath.DeferredShading;UnityEngine.Rendering.GraphicsSettings.lightsUseLinearIntensity=false;preview.DrawMesh(head,Matrix4x4.identity,skin,0);preview.DrawMesh(head,Matrix4x4.identity,eyes,1);RebirthFaceGeneratorWindow.DrawOral(preview,head,oral);preview.DrawMesh(hair,Matrix4x4.identity,mat,0);preview.Render();var image=preview.EndStaticPreview();File.WriteAllBytes(Path.Combine(review,"Fitted_"+style+"_"+angle+".png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}}finally{preview.Cleanup();UnityEngine.Object.DestroyImmediate(hair);UnityEngine.Object.DestroyImmediate(mat);}}
   Debug.Log("REBIRTH_NATIVE_HAIR_FITTED_READY");EditorApplication.Exit(0);
  }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
  public static void Render(){try{
   string output=Environment.GetEnvironmentVariable("REBIRTH_APPEARANCE_OUTPUT");foreach(string p in Directory.GetFiles(Root,"*unitybuiltinshaders.bundle"))AssetBundle.LoadFromFile(p);Bundle("shaders_assets_all.bundle");Bundle("player_assets_entities/player/common.bundle");Bundle("player_assets_entities/player/female/common.bundle");Bundle("player_assets_entities/player/male/common.bundle");
   var female=Model(Bundle("player_assets_entities/player/female/heads/white/01.bundle"));var male=Model(Bundle("player_assets_entities/player/male/heads/white/01.bundle"));
   var styles=new[]{new[]{"female/hair/midpart_long.bundle","hair_midpart_long"},new[]{"female/hair/afro_curly.bundle","hair_afro_curly"},new[]{"female/hair/pixie_cut.bundle","hair_pixie_cut"},new[]{"male/facialhair/beard.bundle","hair_facial_beard3"},new[]{"male/facialhair/mustache.bundle","hair_facial_mustache3"},new[]{"male/facialhair/chops.bundle","hair_facial_sideburns3"}};
   var rows=new List<string>{"Unmodified installed native player heads/hair/facial hair, original shaders/textures/tints, no fitting to custom head."};
   foreach(var style in styles){var model=Model(Bundle("player_assets_entities/player/"+style[0]),style[1]);var head=style[0].StartsWith("female")?female:male;rows.Add(style[0]+" prefab="+model.name);var preview=new PreviewRenderUtility();try{foreach(int angle in new[]{0,90,180}){preview.BeginStaticPreview(new Rect(0,0,1536,1536));RebirthFaceGeneratorWindow.ConfigurePreview(preview,new Vector2(angle,0),.24f,false,null);preview.camera.renderingPath=UnityEngine.RenderingPath.DeferredShading;UnityEngine.Rendering.GraphicsSettings.lightsUseLinearIntensity=false;Draw(preview,head);Draw(preview,model);preview.Render();var image=preview.EndStaticPreview();File.WriteAllBytes(Path.Combine(output,"Native_"+style[1]+"_"+angle+".png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}}finally{preview.Cleanup();}}
   File.WriteAllLines(Path.Combine(output,"NativeReferenceRender.txt"),rows);Debug.Log("REBIRTH_NATIVE_HAIR_REFERENCE_READY");EditorApplication.Exit(0);
  }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 }
}








